public class CadenaMetodos {
    public static double raizCuadrada(double numero) {
        if (numero < 0) {
            throw new IllegalArgumentException("No se puede calcular raíz cuadrada de número negativo: " + numero);
        }
        return Math.sqrt(numero);
    }

    public static double calcular(double valor) throws IllegalArgumentException {
        return raizCuadrada(valor);
    }

    public static void ejecutar(double valor) {
        try {
            double resultado = calcular(valor);
            System.out.println("Raíz cuadrada de " + valor + " = " + resultado);
        } catch (IllegalArgumentException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        ejecutar(25);
        ejecutar(-4);
        ejecutar(16);
    }
}

