public class ValidadorCompleto {
    public static void registrarUsuario(String nombre, int edad, String email) {
        if (nombre == null) {
            throw new NullPointerException("El nombre no puede ser null");
        }
        if (nombre.isEmpty()) {
            throw new IllegalArgumentException("El nombre no puede estar vacío");
        }
        if (edad < 0 || edad > 120) {
            throw new IllegalArgumentException("La edad debe estar entre 0 y 120, valor recibido: " + edad);
        }
        if (email == null) {
            throw new NullPointerException("El email no puede ser null");
        }
        if (!email.contains("@")) {
            throw new ArithmeticException("El email debe ser válido (contener @): " + email);
        }
        System.out.println("Usuario registrado: " + nombre + ", Edad: " + edad + ", Email: " + email);
    }

    public static void main(String[] args) {
        String[][] usuarios = {
            {"Ana", "25", "ana@mail.com"},
            {"", "25", "test@test.com"},
            {"Bob", "-5", "bob@mail.com"},
            {"Carlos", "200", "carlos@mail.com"},
            {"Diana", "30", "null"},
            {"Eve", "22", "eve"}
        };
        for (String[] usuario : usuarios) {
            try {
                registrarUsuario(usuario[0], Integer.parseInt(usuario[1]), usuario[2]);
            } catch (NullPointerException | IllegalArgumentException | ArithmeticException e) {
                System.out.println("Error de validación: " + e.getMessage());
            }
        }
    }
}
